<template>
  <div class="space-y-4 pb-8">
    <PageHeader :title="pageTitle" subtitle="Chứng từ được lưu nháp trước khi ghi sổ và làm phát sinh tiền"><template #actions><Button label="Quay lại" icon="pi pi-arrow-left" size="small" severity="secondary" outlined @click="router.back()" /><Button label="Lưu và ghi sổ" icon="pi pi-check" size="small" :loading="saving" @click="save" /></template></PageHeader>
    <div class="bg-white border border-slate-200 rounded-[6px] p-5 grid grid-cols-1 md:grid-cols-2 gap-4">
      <div><label class="block text-xs font-semibold mb-1">Ngày chứng từ</label><DatePicker v-model="form.voucher_date" date-format="dd/mm/yy" fluid /></div>
      <div><label class="block text-xs font-semibold mb-1">{{ isCash ? 'Quỹ tiền mặt' : 'Tài khoản ngân hàng' }}</label><Select v-model="sourceId" :options="sourceOptions" option-label="label" option-value="value" fluid /></div>
      <div v-if="isTransfer"><label class="block text-xs font-semibold mb-1">Tài khoản ngân hàng nhận</label><Select v-model="destinationId" :options="sourceOptions.filter(item => item.value !== sourceId)" option-label="label" option-value="value" fluid /></div>
      <div v-if="isReceipt" class="md:col-span-2"><label class="block text-xs font-semibold mb-1">Công nợ khách hàng cần thu (không bắt buộc)</label><Select v-model="receivableId" :options="receivableOptions" option-label="label" option-value="value" show-clear filter fluid @change="applyReceivable" /></div>
      <div><label class="block text-xs font-semibold mb-1">Người nộp/người nhận</label><InputText v-model="form.party_name" fluid /></div>
      <div><label class="block text-xs font-semibold mb-1">Số tiền</label><InputNumber v-model="form.total_amount" mode="currency" currency="VND" locale="vi-VN" :min="0" fluid /></div>
      <div class="md:col-span-2"><label class="block text-xs font-semibold mb-1">Diễn giải</label><Textarea v-model="form.description" rows="3" fluid /></div>
    </div>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useToast } from 'primevue/usetoast';
import Button from 'primevue/button'; import DatePicker from 'primevue/datepicker'; import InputNumber from 'primevue/inputnumber'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Textarea from 'primevue/textarea';
import PageHeader from '../../../components/common/PageHeader.vue'; import { financeApi } from '../../../api/finance.api';
const route = useRoute(); const router = useRouter(); const toast = useToast(); const type = computed(() => route.query.type || 'CASH_RECEIPT'); const isCash = computed(() => type.value.startsWith('CASH')); const isReceipt = computed(() => type.value.includes('RECEIPT')); const isTransfer = computed(() => type.value === 'INTERNAL_TRANSFER'); const saving = ref(false); const master = ref({ cash_funds: [], bank_accounts: [] }); const receivables = ref([]); const sourceId = ref(null); const destinationId = ref(null); const receivableId = ref(null);
const form = reactive({ voucher_date: new Date(), party_name: '', description: '', total_amount: 0 });
const pageTitle = computed(() => ({ CASH_RECEIPT: 'Lập Phiếu Thu', CASH_PAYMENT: 'Lập Phiếu Chi', BANK_RECEIPT: 'Lập Chứng Từ Thu Ngân Hàng', BANK_PAYMENT: 'Lập Chứng Từ Chi Ngân Hàng', INTERNAL_TRANSFER: 'Chuyển Tiền Nội Bộ' }[type.value]));
const sourceOptions = computed(() => (isCash.value ? master.value.cash_funds : master.value.bank_accounts).map(item => ({ value: item.id, label: isCash.value ? `${item.code} - ${item.name}` : `${item.bank_name} - ${item.account_number}` })));
const receivableOptions = computed(() => receivables.value.filter(item => item.outstanding_amount > 0).map(item => ({ value: item.id, label: `${item.invoice_number} · ${item.customer_name} · còn ${Number(item.outstanding_amount).toLocaleString('vi-VN')} ₫` })));
const applyReceivable = () => { const item = receivables.value.find(row => row.id === receivableId.value); if (item) { form.party_name = item.customer_name; form.total_amount = item.outstanding_amount; form.description = `Thu tiền hóa đơn ${item.invoice_number}`; } };
const save = async () => { if (!sourceId.value || (isTransfer.value && !destinationId.value) || !form.total_amount || !form.description) { toast.add({ severity: 'warn', summary: 'Thiếu thông tin', detail: 'Vui lòng chọn đầy đủ nguồn tiền, nhập số tiền và diễn giải.', life: 3000 }); return; } saving.value = true; try { const payload = { voucher_type: type.value, channel: isCash.value ? 'CASH' : 'BANK', voucher_date: form.voucher_date.toISOString().slice(0, 10), party_type: receivableId.value ? 'CUSTOMER' : null, party_name: form.party_name, description: form.description, total_amount: form.total_amount, currency: 'VND', cash_fund_id: isCash.value ? sourceId.value : null, bank_account_id: isCash.value ? null : sourceId.value, destination_bank_account_id: isTransfer.value ? destinationId.value : null, counter_account_code: receivableId.value ? '1311' : '138', allocations: receivableId.value ? [{ receivable_id: receivableId.value, amount: form.total_amount }] : [] }; const created = await financeApi.createVoucher(payload); await financeApi.postVoucher(created.data.id); toast.add({ severity: 'success', summary: 'Đã ghi sổ', detail: `Chứng từ ${created.data.voucher_number} đã được ghi sổ.`, life: 3000 }); router.back(); } catch (error) { toast.add({ severity: 'error', summary: 'Không thể ghi sổ', detail: error.message, life: 4000 }); } finally { saving.value = false; } };
onMounted(async () => { const [masterResponse, receivableResponse] = await Promise.all([financeApi.getMasterData(), financeApi.getCustomerReceivables({ per_page: 200 })]); master.value = masterResponse.data; receivables.value = receivableResponse.data || []; const options = isCash.value ? master.value.cash_funds : master.value.bank_accounts; sourceId.value = options[0]?.id || null; destinationId.value = options[1]?.id || null; });
</script>
